cat > /app/plot.py <<'EOF'
import re
x=y=z=0.0
cur=None
segs=[]  # (obj, z, x0,y0,x1,y1)
for line in open('/app/text.gcode'):
    s=line.strip()
    if s.startswith('M486'):
        m=re.match(r'M486 S(-?\d+)',s)
        if m: cur=int(m.group(1))
        continue
    if s.startswith('G1') or s.startswith('G0'):
        nx,ny,nz,e=x,y,z,None
        for tok in s.split()[1:]:
            if tok[0]=='X': nx=float(tok[1:])
            elif tok[0]=='Y': ny=float(tok[1:])
            elif tok[0]=='Z': nz=float(tok[1:])
            elif tok[0]=='E': e=float(tok[1:])
        if e is not None and e>0 and (nx!=x or ny!=y):
            segs.append((cur,z,x,y,nx,ny))
        x,y,z=nx,ny,nz
# object 0 = Embossed text
zs=sorted(set(round(zz,3) for o,zz,*_ in segs if o==0))
print("obj0 zlayers count", len(zs), zs[:20])
print("total obj0 segs", sum(1 for s in segs if s[0]==0))
EOF
python3 /app/plot.py
